import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

deconv3d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void transposed_conv3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N,
    int inC,
    int inD,
    int inH,
    int inW,
    int outC,
    int kernel,
    int stride,
    int pad,
    int dilation,
    int out_pad,
    int outD,
    int outH,
    int outW,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * outC * outD * outH * outW;
    if (idx >= total) return;

    int ow = idx % outW; 
    int tmp = idx / outW;
    int oh = tmp % outH; 
    tmp /= outH;
    int od = tmp % outD;
    tmp /= outD;
    int co = tmp % outC;
    int n = tmp / outC;

    float val = 0.0f;
    for (int ci = 0; ci < inC; ci++) {
        for (int kd = 0; kd < kernel; kd++) {
            int id = od + pad - kd * dilation;
            if (id % stride == 0) {
                id /= stride;
                if (id >= 0 && id < inD) {
                    for (int kh = 0; kh < kernel; kh++) {
                        int ih = oh + pad - kh * dilation;
                        if (ih % stride == 0) {
                            ih /= stride;
                            if (ih >= 0 && ih < inH) {
                                for (int kw = 0; kw < kernel; kw++) {
                                    int iw = ow + pad - kw * dilation;
                                    if (iw % stride == 0) {
                                        iw /= stride;
                                        if (iw >= 0 && iw < inW) {
                                            float iv = input[ (((n * inC + ci) * inD + id) * inH + ih) * inW + iw ];
                                            float wv = weight[ ((((ci * outC) + co) * kernel + kd) * kernel + kh) * kernel + kw ];
                                            val += iv * wv;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if (has_bias) {
        val += bias[co];
    }
    output[idx] = val;
}

torch::Tensor transposed_conv3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int output_padding
) {
    auto in_sizes = input.sizes();
    int N = in_sizes[0];
    int inC = in_sizes[1];
    int inD = in_sizes[2];
    int inH = in_sizes[3];
    int inW = in_sizes[4];

    auto w_sizes = weight.sizes();
    // weight shape: [inC, outC, k, k, k]
    int kernel = w_sizes[2];
    int outC = w_sizes[1];

    int outD = (inD - 1) * stride - 2 * padding + (kernel - 1) * dilation + 1 + output_padding;
    int outH = (inH - 1) * stride - 2 * padding + (kernel - 1) * dilation + 1 + output_padding;
    int outW = (inW - 1) * stride - 2 * padding + (kernel - 1) * dilation + 1 + output_padding;

    auto options = input.options();
    auto output = torch::zeros({N, outC, outD, outH, outW}, options);

    int total = N * outC * outD * outH * outW;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    bool has_bias = bias.numel() > 0;

    transposed_conv3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N,
        inC,
        inD,
        inH,
        inW,
        outC,
        kernel,
        stride,
        padding,
        dilation,
        output_padding,
        outD,
        outH,
        outW,
        has_bias
    );

    return output;
}
"""

deconv3d_cpp_source = r"""
torch::Tensor transposed_conv3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int output_padding
);
"""

deconv3d_op = load_inline(
    name="deconv3d_op",
    cpp_sources=deconv3d_cpp_source,
    cuda_sources=deconv3d_source,
    functions=["transposed_conv3d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, 
                 stride: int = 1, padding: int = 0, output_padding: int = 0, 
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        # groups is ignored in this custom kernel for simplicity
        self.has_bias = bias

        self.weight = nn.Parameter(
            torch.randn(in_channels, out_channels, kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return deconv3d_op.transposed_conv3d_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([], device=x.device),
            self.stride,
            self.padding,
            self.dilation,
            self.output_padding
        )
